-- 3) Translation cache (makes package/destination content translate)
CREATE TABLE IF NOT EXISTS `translations` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `locale` VARCHAR(10) NOT NULL,
  `source_hash` VARCHAR(40) NOT NULL,
  `source_text` TEXT NOT NULL,
  `translated_text` TEXT NOT NULL,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `translations_locale_source_hash_unique` (`locale`,`source_hash`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- 4) Mark migrations as run (keeps artisan migrate consistent)
SET @b = (SELECT COALESCE(MAX(`batch`),0)+1 FROM `migrations`);
